import{_ as o,l as s,o as e,c as n,v as r,p as l,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"前向保密","description":"","frontmatter":{"title":"前向保密","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/forward-secrecy.md","filePath":"cs/forward-secrecy.md","lastUpdated":1789023840000}'),E={name:"cs/forward-secrecy.md"};function p(f,a,_,A,m,u){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="前向保密" tabindex="-1">前向保密 <a class="header-anchor" href="#前向保密" aria-label="Permalink to &quot;前向保密&quot;">​</a></h1><div class="epigraph"><p>长期私钥将来泄漏，也不该能解开过去的会话。做法是每次用临时 DH，会话键用完即忘；静态 RSA 封装做不到这一点。</p><footer>—— Diffie, van Oorschot and Wiener, Authentication and Authenticated Key Exchanges, 1992；RFC 8446 对 (EC)DHE 的选择</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/key-management-hsm">密钥管理</a>保护长期根。缺口是<strong>根仍可能在某天泄漏</strong>（备份、强制、漏洞）。前向保密把历史会话从根的命运里摘出去。主干<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a>已点名；本课升为主题。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 RSA 封装：谁拿到长期 \\(d\\)，谁解密所有被封过的 \\(k\\)。ECDHE：临时标量丢弃后，长期签钥只能伪造未来，不能回溯旧 AEAD 键。缺口是会话键的遗忘策略：内存、日志、核心转储都不要留下 \\(k\\)。</p><h3 id="_0-rtt-会打折" tabindex="-1">0-RTT 会打折 <a class="header-anchor" href="#_0-rtt-会打折" aria-label="Permalink to &quot;0-RTT 会打折&quot;">​</a></h3><p><a href="/cs/tls13-0rtt">TLS 1.3 0-RTT</a> 用 PSK 提前发数据，有重放与弱前向窗口。可用性与遗忘在此打架。</p><p><span class="marginnote">Diffie–van Oorschot–Wiener 的认证密钥交换讨论 PFS。本课不给「如何从服务器抠过去会话」的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照静态封装 vs 临时 DH。要求：临时密钥在握手后清零；长期钥只做签名或认证。指出记录层序号防重放，但不等于 PFS。</p>',12)),(e(),l(h,null,{default:t(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EPHEM%5B%22%E4%B8%B4%E6%97%B6%20ECDHE%22%5D%20--%3E%20SK%5B%22%E4%BC%9A%E8%AF%9D%E9%94%AE%22%5D%0A%20%20SK%20--%3E%20FORGET%5B%22%E7%94%A8%E5%90%8E%E6%B8%85%E9%9B%B6%22%5D%0A%20%20LONG%5B%22%E9%95%BF%E6%9C%9F%E7%AD%BE%E9%92%A5%22%5D%20--%3E%20AUTH%5B%22%E8%AE%A4%E8%AF%81%E6%8F%A1%E6%89%8B%22%5D%0A%20%20LONG%20-.-%3E%7C%22%E6%B3%84%E6%BC%8F%E4%B8%8D%E8%A7%A3%E5%AF%86%E8%BF%87%E5%8E%BB%22%7C%20SK%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HSM 里的长期钥仍值得关；PFS 保证关不住的那一天历史仍在计算上保密。Signal 下一课把「多次会话」收成棘轮，使更细粒度的遗忘成为可能。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把后量子 KEM 提前展开。双棘轮下一课：每条消息都可以进一格，前向与后向保密的工程形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HSM 护根；PFS 让根的未来泄漏不回溯。</li><li>临时 DH + 遗忘会话键；静态 RSA 封装无此性质。</li><li>0-RTT 与日志里的 \\(k\\) 会削弱遗忘。</li><li>下一课 Signal 双棘轮。</li><li>出处：Diffie, van Oorschot and Wiener, 1992；RFC 8446。</li></ul>',8))])}const B=o(E,[["render",p]]);export{T as __pageData,B as default};
